95	    },
96	    {
97	      "rule": "claudinite-isolation",
98	      "path": "scripts/verify.sh",
99	      "reason": "the repo's one verification gate invokes the world sweep (engine/checks/check_the_world.mjs) so that passing it locally means what passing CI means — a commit that passed verify and went red on CI for a blocking conformance finding is what prompted this. Not the coupling the rule guards against: no canon internals are imported and nothing is inlined, it is the same documented CLI entry point .github/workflows/ already spells under the rule's own carve-out. A canon rename of that one path breaks the workflow and this script identically, and the fix is the same one line"
100	    }
101	  ],
102	  "taskScheduler": {
103	    "agenticTaskInvocationEndpoints": {
104	      "default": {
